//! Shell integration.
//!
//! A terminal learns nothing from a shell that does not talk back. These small
//! scripts make a shell announce where it is (OSC 7) and where its prompts
//! begin, end and finish, with the exit status (OSC 133). That is what lets a
//! pane header show the working directory and what lets a key jump between
//! prompts instead of scrolling.
//!
//! Nothing is installed into a person's dotfiles. The scripts are generated by
//! the app and applied per pane, so removing the app removes them. The shell's
//! own prompt is preserved and called, not replaced.

use std::io;
use std::path::Path;

/// A shell whose prompt we know how to instrument.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Family {
    PowerShell,
    Bash,
}

impl Family {
    /// File the script is written to, for the families that need one on disk.
    pub fn script_file_name(self) -> &'static str {
        match self {
            Family::PowerShell => "integration.ps1",
            Family::Bash => "integration.bash",
        }
    }

    /// The integration script itself.
    pub fn script(self) -> &'static str {
        match self {
            Family::PowerShell => POWERSHELL,
            Family::Bash => BASH,
        }
    }
}

/// The family for a program path, if it is one we instrument.
pub fn family_of(program: &str) -> Option<Family> {
    let file_name = program
        .rsplit(['/', '\\'])
        .next()
        .unwrap_or(program)
        .to_ascii_lowercase();
    let stem = file_name
        .strip_suffix(".exe")
        .unwrap_or(&file_name)
        .to_string();

    match stem.as_str() {
        "pwsh" | "powershell" => Some(Family::PowerShell),
        "bash" => Some(Family::Bash),
        _ => None,
    }
}

/// Arguments that make `program` run the integration.
///
/// The caller's own arguments come first and are kept: a profile that already
/// passes flags to its shell should still get them. Returns the arguments
/// unchanged when the shell is not one we know, so an unknown shell is never
/// started with flags it does not understand.
pub fn integrate(program: &str, args: &[String], directory: &Path) -> io::Result<Vec<String>> {
    let Some(family) = family_of(program) else {
        return Ok(args.to_vec());
    };

    let mut merged = args.to_vec();
    match family {
        Family::PowerShell => {
            // -EncodedCommand takes the script as UTF-16LE base64. The script
            // never touches the disk, and the execution policy is not involved
            // because nothing is being read from a file.
            merged.push("-NoLogo".to_string());
            merged.push("-NoExit".to_string());
            merged.push("-EncodedCommand".to_string());
            merged.push(encode_powershell_command(family.script()));
        }
        Family::Bash => {
            std::fs::create_dir_all(directory)?;
            let path = directory.join(family.script_file_name());
            std::fs::write(&path, family.script())?;
            merged.push("--rcfile".to_string());
            merged.push(path.to_string_lossy().into_owned());
        }
    }
    Ok(merged)
}

/// Base64 of a PowerShell command encoded as UTF-16LE, which is what
/// `-EncodedCommand` expects.
pub fn encode_powershell_command(script: &str) -> String {
    let bytes: Vec<u8> = script
        .encode_utf16()
        .flat_map(|unit| unit.to_le_bytes())
        .collect();
    base64(&bytes)
}

/// Base64 without a dependency: the whole alphabet is sixteen lines.
fn base64(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let first = chunk[0] as u32;
        let second = *chunk.get(1).unwrap_or(&0) as u32;
        let third = *chunk.get(2).unwrap_or(&0) as u32;
        let triple = (first << 16) | (second << 8) | third;

        out.push(ALPHABET[(triple >> 18) as usize & 63] as char);
        out.push(ALPHABET[(triple >> 12) as usize & 63] as char);
        out.push(if chunk.len() > 1 {
            ALPHABET[(triple >> 6) as usize & 63] as char
        } else {
            '='
        });
        out.push(if chunk.len() > 2 {
            ALPHABET[triple as usize & 63] as char
        } else {
            '='
        });
    }
    out
}

const POWERSHELL: &str = r#"# HyperPane shell integration.
# Reached through -EncodedCommand: nothing is written to disk and the execution
# policy is not involved.

$env:HYPERPANE_INTEGRATION = '1'
$global:HyperPaneEsc = [char]27
$global:HyperPaneBel = [char]7

function global:__HyperPaneEmit([string]$text) {
    Write-Host -NoNewline $text
}

# Keep whatever prompt the profile installed. Replacing it would be rude and
# would make the integration something to work around.
$global:HyperPanePrompt = if (Test-Path Function:\prompt) { $function:prompt } else { $null }
# The first prompt has no previous command, so it reports no status.
$global:HyperPanePromptSeen = $false

function global:prompt {
    # These two lines must come first. $? holds the status of the last command,
    # and any statement before this point - including the test inside an if -
    # would overwrite it.
    $ok = $?
    $lastNative = $LASTEXITCODE

    if ($global:HyperPanePromptSeen) {
        $exit = 0
        if (-not $ok) {
            if ($lastNative -is [int] -and $lastNative -ne 0) { $exit = $lastNative } else { $exit = 1 }
        }
        # D: the previous command finished, with its status.
        __HyperPaneEmit "$HyperPaneEsc]133;D;$exit$HyperPaneBel"
    }
    $global:HyperPanePromptSeen = $true

    $path = (Get-Location).ProviderPath -replace '\\', '/'
    # OSC 7: where we are now.
    __HyperPaneEmit "$HyperPaneEsc]7;file://$env:COMPUTERNAME/$path$HyperPaneBel"
    # A: the prompt begins.
    __HyperPaneEmit "$HyperPaneEsc]133;A$HyperPaneBel"

    if ($global:HyperPanePrompt) {
        & $global:HyperPanePrompt
    } else {
        "PS $($executionContext.SessionState.Path.CurrentLocation)$('>' * ($nestedPromptLevel + 1)) "
    }

    # B: the prompt ends, so the command the person types starts here.
    __HyperPaneEmit "$HyperPaneEsc]133;B$HyperPaneBel"
}
"#;

const BASH: &str = r#"# HyperPane shell integration.
# Applied with --rcfile, so nothing is installed into your dotfiles.

if [ -n "$HYPERPANE_INTEGRATION" ]; then
  return
fi
export HYPERPANE_INTEGRATION=1

# Load whatever this shell would normally have loaded. --rcfile replaces the
# usual startup file, so the original has to be sourced back in.
if [ -f "$HOME/.bashrc" ]; then
  . "$HOME/.bashrc"
fi

__hyperpane_report() {
  local status=$?
  printf '\033]133;D;%s\007' "$status"
  printf '\033]7;file://%s%s\007' "${HOSTNAME:-localhost}" "$PWD"
}

# PS0 runs after a command is read and before it executes, which is the only
# place bash can mark the start of a command.
__hyperpane_command_start() {
  printf '\033]133;C\007'
}

PROMPT_COMMAND="__hyperpane_report${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
PS0='$(__hyperpane_command_start)'"${PS0:-}"

# A before the prompt, B after it: readline markers keep the escapes from
# counting towards the prompt width.
PS1='\[\033]133;A\007\]'"${PS1:-}"'\[\033]133;B\007\]'
"#;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn recognises_a_shell_by_name_and_path() {
        assert_eq!(family_of("pwsh.exe"), Some(Family::PowerShell));
        assert_eq!(family_of("powershell"), Some(Family::PowerShell));
        assert_eq!(
            family_of(r"C:\Program Files\PowerShell\7\pwsh.exe"),
            Some(Family::PowerShell)
        );
        assert_eq!(family_of("/bin/bash"), Some(Family::Bash));
        assert_eq!(family_of("bash.exe"), Some(Family::Bash));
    }

    #[test]
    fn does_not_claim_an_unknown_shell() {
        assert_eq!(family_of("zsh"), None);
        assert_eq!(family_of("cmd.exe"), None);
        assert_eq!(family_of("my-bash-wrapper"), None);
    }

    #[test]
    fn an_unknown_shell_keeps_its_arguments_untouched() {
        let args = vec!["-i".to_string()];
        let merged = integrate("zsh", &args, Path::new(".")).expect("no io");
        assert_eq!(merged, args);
    }

    #[test]
    fn powershell_gets_an_encoded_command_and_no_file() {
        let dir = std::env::temp_dir().join("hp-shell-powershell");
        let _ = std::fs::remove_dir_all(&dir);

        let merged = integrate("pwsh.exe", &[], &dir).expect("integrate");
        assert_eq!(merged[merged.len() - 2], "-EncodedCommand");
        assert!(!dir.exists(), "PowerShell needs no file on disk");

        let decoded = decode_powershell(merged.last().expect("payload"));
        assert!(decoded.contains("]133;A"), "prompt start marker");
        assert!(decoded.contains("]7;file://"), "directory report");
        assert!(
            decoded.contains("Test-Path Function:\\prompt"),
            "keeps the prompt"
        );
    }

    #[test]
    fn a_profile_argument_is_kept_and_the_integration_follows_it() {
        let dir = std::env::temp_dir().join("hp-shell-args");
        let args = vec!["-NoProfile".to_string()];
        let merged = integrate("powershell.exe", &args, &dir).expect("integrate");
        assert_eq!(merged[0], "-NoProfile");
        assert!(merged.contains(&"-EncodedCommand".to_string()));
    }

    #[test]
    fn bash_gets_an_rcfile_that_sources_the_original() {
        let dir = std::env::temp_dir().join("hp-shell-bash");
        let _ = std::fs::remove_dir_all(&dir);

        let merged = integrate("/bin/bash", &[], &dir).expect("integrate");
        assert_eq!(merged[0], "--rcfile");

        let script = std::fs::read_to_string(&merged[1]).expect("script written");
        assert!(
            script.contains(". \"$HOME/.bashrc\""),
            "sources the user rc"
        );
        assert!(script.contains("]133;D;"), "reports the exit status");
        assert!(script.contains("]7;file://"), "reports the directory");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// The test vectors from RFC 4648, section 10.
    #[test]
    fn base64_matches_the_reference_vectors() {
        assert_eq!(base64(b""), "");
        assert_eq!(base64(b"f"), "Zg==");
        assert_eq!(base64(b"fo"), "Zm8=");
        assert_eq!(base64(b"foo"), "Zm9v");
        assert_eq!(base64(b"foob"), "Zm9vYg==");
        assert_eq!(base64(b"fooba"), "Zm9vYmE=");
        assert_eq!(base64(b"foobar"), "Zm9vYmFy");
    }

    #[test]
    fn a_powershell_command_round_trips_through_the_encoder() {
        let script = "Write-Host 'héllo'";
        let decoded = decode_powershell(&encode_powershell_command(script));
        assert_eq!(decoded, script);
    }

    /// Decodes what `-EncodedCommand` expects, for the tests above.
    fn decode_powershell(encoded: &str) -> String {
        let mut bytes = Vec::new();
        let mut buffer: u32 = 0;
        let mut bits = 0;
        for character in encoded.bytes() {
            let value = match character {
                b'A'..=b'Z' => character - b'A',
                b'a'..=b'z' => character - b'a' + 26,
                b'0'..=b'9' => character - b'0' + 52,
                b'+' => 62,
                b'/' => 63,
                _ => continue,
            } as u32;
            buffer = (buffer << 6) | value;
            bits += 6;
            if bits >= 8 {
                bits -= 8;
                bytes.push((buffer >> bits) as u8);
            }
        }

        let mut units: Vec<u16> = Vec::with_capacity(bytes.len() / 2);
        let mut index = 0;
        while index + 2 <= bytes.len() {
            units.push(u16::from_le_bytes([bytes[index], bytes[index + 1]]));
            index += 2;
        }
        String::from_utf16(&units).expect("valid utf-16")
    }
}
